param([string]$InputPath = (Join-Path $PSScriptRoot 'maidata.txt')); $ErrorActionPreference = 'Stop'; $ScriptPath = Join-Path $PSScriptRoot 'maimai_analyzer.py'; $OutputPath = Join-Path $PSScriptRoot 'analysis_output'; if (Get-Command py -ErrorAction SilentlyContinue) { & py -3 $ScriptPath $InputPath --out $OutputPath --open } elseif (Get-Command python -ErrorAction SilentlyContinue) { & python $ScriptPath $InputPath --out $OutputPath --open } else { throw 'Python 3.10+ is required. Install Python and add it to PATH.' }; if ($LASTEXITCODE -ne 0) { throw "Analyzer exited with code $LASTEXITCODE" }
